//! Dataset loading for Texel tuning.
//!
//! ## File format
//!
//! One position per line:
//!
//! ```text
//! <FEN>  <result>
//! ```
//!
//! where `<result>` is one of `1.0` (White wins), `0.5` (draw), `0.0` (Black wins).
//!
//! Lines starting with `#` are comments and are ignored.
//!
//! ## Example
//!
//! ```text
//! # generated by checksmith datagen
//! rnbqkbnr/pppppppp/8/8/4P3/8/PPPP1PPP/RNBQKBNR b KQkq e3 0 1 1.0
//! r1bqkb1r/pppp1ppp/2n2n2/4p3/2B1P3/5N2/PPPP1PPP/RNBQK2R b KQkq e6 0 4 0.5
//! ```

use crate::board::Board;
use crate::tune::params::{compute_trace, EvalTrace};
use std::fs::File;
use std::io::{BufRead, BufReader, BufWriter, Write};
use std::path::Path;

/// A single training example: the evaluation trace of a position plus the
/// game result from White's perspective.
pub struct Entry {
    pub trace:   EvalTrace,
    /// 1.0 = White wins, 0.5 = draw, 0.0 = Black wins.
    pub outcome: f64,
    /// True if it was White's turn to move when the position was recorded.
    pub white_to_move: bool,
}

/// Load a dataset from a text file.
///
/// Invalid FENs are skipped with a warning.  Returns an error if the file
/// cannot be opened.
pub fn load(path: &Path) -> std::io::Result<Vec<Entry>> {
    let file   = File::open(path)?;
    let reader = BufReader::new(file);
    let mut entries = Vec::new();
    let mut skipped = 0usize;

    for (line_no, line) in reader.lines().enumerate() {
        let line = line?;
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') { continue; }

        // Last token is the result; everything before it is the FEN.
        let Some((fen, result_str)) = line.rsplit_once(' ') else {
            eprintln!("line {}: missing result field, skipping", line_no + 1);
            skipped += 1;
            continue;
        };
        let outcome: f64 = match result_str.trim() {
            "1.0" | "1-0" => 1.0,
            "0.5" | "1/2-1/2" => 0.5,
            "0.0" | "0-1" => 0.0,
            other => {
                eprintln!("line {}: unrecognised result '{}', skipping", line_no + 1, other);
                skipped += 1;
                continue;
            }
        };

        match Board::from_fen(fen) {
            Ok(board) => {
                let trace = compute_trace(&board);
                let white_to_move = board.side_to_move == crate::board::Color::White;
                entries.push(Entry { trace, outcome, white_to_move });
            }
            Err(e) => {
                eprintln!("line {}: bad FEN ({}) — skipping", line_no + 1, e);
                skipped += 1;
            }
        }
    }

    if skipped > 0 {
        eprintln!("warning: skipped {} invalid lines", skipped);
    }
    eprintln!("loaded {} positions", entries.len());
    Ok(entries)
}

/// Save a list of raw FEN + result lines to a text file.
pub fn save_raw(lines: &[String], path: &Path) -> std::io::Result<()> {
    let file   = File::create(path)?;
    let mut w  = BufWriter::new(file);
    writeln!(w, "# generated by checksmith datagen")?;
    for line in lines { writeln!(w, "{}", line)?; }
    Ok(())
}
